<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Teacher','Bursar','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}$id=filter_var($_POST['request_id']??null,FILTER_VALIDATE_INT);if(!$id){$_SESSION['error']='A valid leave request is required.';header('Location: ../?page=staffing');exit;}$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,staff_id,status FROM staff_leave_requests WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$request=$q->fetch();if(!$request||(int)$request['staff_id']!==(int)$user['id']||$request['status']!=='Pending')throw new DomainException('You can cancel only your own pending leave requests.');$q=$pdo->prepare("UPDATE staff_leave_requests SET status='Cancelled' WHERE id=:id AND status='Pending'");$q->execute(['id'=>$id]);$q=$pdo->prepare("INSERT INTO staff_leave_reviews(leave_request_id,from_status,to_status,notes,reviewed_by) VALUES(:id,'Pending','Cancelled','Cancelled by requester',:user)");$q->execute(['id'=>$id,'user'=>$user['id']]);audit_log('staff.leave_cancelled','staff_leave_requests',$id);$pdo->commit();$_SESSION['notice']='Pending leave request cancelled.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Staff leave cancel failed: '.$e->getMessage());$_SESSION['error']='Could not cancel the leave request.';}header('Location: ../?page=staffing');exit;
